import { test, expect } from 'bun:test';

test('total of empty array', () => {
  expect(total([])).toBe(0);
});

test('total of numbers', () => {
  expect(total([1, 2, 3])).toBe(6);
  expect(total([1, 2, 3, 4, 5])).toBe(15);
});

test('total of non-numeric values', () => {
  expect(() => total([1, 'a', 3])).toThrow();
});

test('total of non-finite values', () => {
  expect(() => total([1, Infinity, 3])).toThrow();
});

